import { resolvers } from '@hozu/data'
import { app } from '@hozu/runtime-server'
import project from './hozu.config.ts'
import { notesResolvers } from './features/notes/server.ts'
import { accountResolvers } from './features/account/server.ts'
import { createUndoStore } from './features/notes/undo.ts'
import { createUserDirectory } from './features/account/users.ts'
import { createNoteStore } from './features/notes/store.ts'

const undo = createUndoStore()
const users = createUserDirectory()
const notes = createNoteStore()

export default app({
  resolvers: resolvers(project, (implement) => [
    ...accountResolvers(implement, undo, users, notes),
    ...notesResolvers(implement, undo, users, notes),
  ]),
})
import { project, ui } from '@hozu/core'
import { zodAdapter } from '@hozu/schema-zod'
import { admin, archive, deleteAccount, home, login, notePage } from './routes.ts'
import { AdminBoard, ArchiveBoard, NotePage, NotesBoard } from './features/notes/views.ts'
import { notes } from './features/notes/feature.ts'
import { adminUsers, getNote } from './features/notes/model.ts'
import { me, Session } from './features/account/model.ts'
import { AccountBar, DeleteAccountPage, Login } from './features/account/views.ts'
import { account } from './features/account/feature.ts'
import { text as accountText } from './features/account/text.ts'
import { text as notesText } from './features/notes/text.ts'

export default project({
  schema: zodAdapter,
  session: Session,
  styles: new URL('./app.css', import.meta.url),
  app: new URL('./app.ts', import.meta.url),
  env: { files: ['.env', '.env.local'] },
  site: { url: 'http://localhost:3000', name: 'app', lang: 'en', locales: ['en', 'de'] },
  routes: {home, login, archive, admin, deleteAccount, notePage},
  pages: [
    ui.page(login, { views: [Login], head: { render: () => ({ title: accountText.signIn }) } }),
    ui.page(home, {
      views: [AccountBar, NotesBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: notesText.notes, noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(archive, {
      views: [AccountBar, ArchiveBoard],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Archive', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(notePage, {
      views: [AccountBar, NotePage],
      head: {
        query: getNote,
        input: (params) => ({ number: params.number }),
        render: (note) => ({ title: note.title, noindex: true }),
        failed: { Unauthorized: login, NotFound: 404 },
      },
    }),
    ui.page(deleteAccount, {
      views: [AccountBar, DeleteAccountPage],
      head: {
        query: me,
        input: () => ({}),
        render: () => ({ title: 'Delete account', noindex: true }),
        failed: { Unauthorized: login },
      },
    }),
    ui.page(admin, {
      views: [AccountBar, AdminBoard],
      head: {
        query: adminUsers,
        input: () => ({}),
        render: () => ({ title: 'Admin', noindex: true }),
        failed: { Unauthorized: login, Forbidden: 403 },
      },
    })],
  features: [account, notes],
})
import { feature } from '@hozu/core'
import * as model from './model.ts'
import * as views from './views.ts'
import * as text from './text.ts'

export const account = feature({
  id: 'account',
  intent: { summary: 'Sign in with a name, sign out; the session identifies the user' },
  exports: [model.me],
  declarations: [model, views, text],
})
import { endpoint, event, invoke, machine, mutation, on, query, ui } from '@hozu/core'
import { z } from 'zod'
import { home, login } from '../../routes.ts'

export const Session = z.object({ user: z.string() })
export const Name = z.object({ name: z.string().regex(/^\s*[A-Za-z]{2,20}\s*$/, 'Use 2–20 letters') })

export const SignIn = event({ payload: z.object({ name: z.string() }) })
export const SignOut = event({ payload: z.object({}) })
export const DeleteAccount = event({ payload: z.object({}) })

export const me = query({
  input: z.object({}),
  output: z.object({ name: z.string(), admin: z.boolean() }),
  errors: { Unauthorized: z.object({}) },
  scope: 'user',
  freshness: 'request',
  runs: 'server',
})

export const signIn = mutation({ input: Name, output: z.object({}), runs: 'server' })
export const signOut = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })
export const removeAccount = mutation({ input: z.object({}), output: z.object({}), runs: 'server' })

export const root = endpoint({ method: 'GET', path: '/', input: z.object({}), output: 'redirect' })

export const accountMachine = machine({
  context: z.object({
    draft: z.string(),
    error: z.string().nullable(),
    fields: z.object({ name: z.string().nullable() }),
  }),
  initialContext: { draft: '', error: null, fields: { name: null } },
  initial: 'idle',
  states: ({ ctx }) => ({
    idle: {
      on: [
        on(SignIn, {
          target: 'signingIn',
          assign: (e) => { ctx.draft = e.name; ctx.error = null; ctx.fields = { name: null } },
        }),
        on(SignOut, { target: 'signingOut' }),
        on(DeleteAccount, { target: 'deletingAccount', assign: () => { ctx.error = null } }),
      ],
    },
    signingIn: {
      invoke: invoke(signIn, {
        input: { name: ctx.draft },
        done: { target: 'idle', navigate: () => ui.link(home, null) },
        failed: {
          Invalid: { target: 'idle', assign: (e) => { ctx.fields = e.fields } },
          Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } },
        },
      }),
    },
    signingOut: {
      invoke: invoke(signOut, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
    deletingAccount: {
      invoke: invoke(removeAccount, {
        input: {},
        done: { target: 'idle', navigate: () => ui.link(login, null, { deleted: true }) },
        failed: { Unexpected: { target: 'idle', assign: (e) => { ctx.error = e.message } } },
      }),
    },
  }),
})
import type { Implement } from '@hozu/data'
import { ui } from '@hozu/core'
import { home, login } from '../../routes.ts'
import { me, removeAccount, root, signIn, signOut } from './model.ts'
import { type UndoStore, undoKeyOf } from '../notes/undo.ts'
import { type UserDirectory, isAdmin } from './users.ts'
import { type NoteStore, purgeUser } from '../notes/store.ts'

export function accountResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  return [
    implement(me, (_, { session, fail }) => (session ? { name: session.user, admin: isAdmin(session) } : fail('Unauthorized', {}))),
    implement(root, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
      setSession({ user: name.trim() })
      users.set(name.trim().toLowerCase(), name.trim())
      return {}
    }),
    implement(signOut, (_, { session, setSession }) => {
      if (session) undo.delete(undoKeyOf(session))
      setSession(null)
      return {}
    }),
    implement(removeAccount, (_, { session, setSession }) => {
      if (session) {
        const key = session.user.trim().toLowerCase()
        purgeUser(notes, key)
        users.delete(key)
        undo.delete(undoKeyOf(session))
      }
      setSession(null)
      return {}
    }),
  ]
}
import { ui } from '@hozu/core'

