      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      forget(session)
      return view(item)
    }),
    implement(editNote, ({ id, title, body }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      const cleanBody = body.replace(/\r\n?/g, '\n').trim()
      const titleError =
        cleanTitle.length === 0 ? 'Write a title first'
          : cleanTitle.length > 60 ? 'Use at most 60 characters'
          : items.some((entry) => entry.id !== id && entry.title.toLowerCase() === cleanTitle.toLowerCase()) ? 'You already have a note with this title'
          : null
      const bodyError = cleanBody.length > 1000 ? 'Use at most 1000 characters in the body' : null
      if (titleError !== null || bodyError !== null)
        return fail('Invalid', { message: 'Check the title and body', fields: { title: titleError, body: bodyError } })
      item.title = cleanTitle
      item.body = cleanBody
      forget(session)
      return view(item)
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      forget(session)
      return view(item)
    }),
  ]
}
import type { Item } from './undo.ts'

// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // Highest note number each user has ever had; numbers are never reused.
  numbers: Map<string, number>
  nextId: () => string
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  const seed = (notes: [string, string][]) => {
    // Numbered in the order they were added, oldest first.
    const oldestFirst = [...notes].sort(([, a], [, b]) => a.localeCompare(b))
    return notes.map(([title, createdAt]) => ({ id: nextId(), number: oldestFirst.findIndex(([t]) => t === title) + 1, title, body: '', pinned: false, createdAt, archived: false, sharedWith: [] as string[] }))
  }
  const notes = new Map<string, Item[]>([
    ['ada', seed([['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])],
    ['bob', seed([["Bob's secret", '2026-01-10T09:00:00.000Z']])],
  ])
  return {
    notes,
    owners: new Map(),
    added: new Map(),
    numbers: new Map([...notes].map(([key, items]) => [key, Math.max(0, ...items.map((item) => item.number))])),
    nextId,
  }
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing and add history.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
}
export type Item = { id: string; number: number; title: string; body: string; pinned: boolean; createdAt: string; archived: boolean; sharedWith: string[] }

// The most recent delete per user, kept until it is undone, the user's notes change again or the user signs out.
export type UndoStore = Map<string, { item: Item; at: number }>

export const createUndoStore = (): UndoStore => new Map()

